describe('Dynamic Content Updates Accessibility', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should announce dynamic content updates to screen readers', () => {
        // Simulate a dynamic content update
        cy.get('#dynamic-content').should('exist');
        cy.get('#update-button').click(); // Assume this button triggers the update

        // Check if the updated content is present
        cy.get('#dynamic-content').should('contain', 'New content has been loaded');

        // Verify that the screen reader announces the update
        cy.get('#dynamic-content').invoke('attr', 'aria-live').should('equal', 'polite');
    });

    it('should not announce updates when aria-live is set to off', () => {
        // Simulate a dynamic content update
        cy.get('#dynamic-content').should('exist');
        cy.get('#update-button').click(); // Assume this button triggers the update

        // Check if the updated content is present
        cy.get('#dynamic-content').should('contain', 'New content has been loaded');

        // Verify that the screen reader does not announce the update
        cy.get('#dynamic-content').invoke('attr', 'aria-live').should('equal', 'off');
    });
});
